const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
const fmtTime=s=>s?new Date(s).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}):'—';
const tomorrow=()=>{let d=new Date();d.setDate(d.getDate()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
let data=null, view='dashboard', category='All', query='', bookFilter='All', profileOpen=false, noticeOpen=false, sideOpen=false, assistantOpen=false, chat=[{from:'bot',text:'Hi! I’m LabMate, your campus resource guide. Ask me to find suitable equipment, understand training requirements, or check your bookings. I use the current demo data and transparent rules.'}], photoValue='';
const paths={home:'<path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 22V12h6v10"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/>',spark:'<path d="m12 3 1.9 6.1L20 11l-6.1 1.9L12 19l-1.9-6.1L4 11l6.1-1.9L12 3zM19 18l.6 1.4L21 20l-1.4.6L19 22l-.6-1.4L17 20l1.4-.6L19 18z"/>',history:'<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l4 3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .4 1.9l.1.1-2 2-.1-.1a1.7 1.7 0 0 0-1.9-.4 1.7 1.7 0 0 0-1 1.6V21h-3v-.1a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.4l-.1.1-2-2 .1-.1a1.7 1.7 0 0 0 .4-1.9 1.7 1.7 0 0 0-1.6-1H5v-3h.1a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.4-1.9l-.1-.1 2-2 .1.1a1.7 1.7 0 0 0 1.9.4 1.7 1.7 0 0 0 1-1.6V5h3v.1a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.4l.1-.1 2 2-.1.1a1.7 1.7 0 0 0-.4 1.9 1.7 1.7 0 0 0 1.6 1h.1v3h-.1a1.7 1.7 0 0 0-1.6 1z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m6 9 6 6 6-6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',arrowup:'<path d="m7 17 10-10M8 7h9v9"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2.5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',check:'<path d="m4 12 5 5L20 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',plus:'<path d="M12 5v14M5 12h14"/>',printer:'<rect x="3" y="7" width="18" height="12" rx="2"/><path d="M7 7V3h10v4M7 16h10v5H7zM17 11h1"/><path d="M8 13h8"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2z"/><circle cx="12" cy="14" r="5"/><circle cx="12" cy="14" r="2"/>',room:'<path d="M4 21V4h16v17M4 21h16M8 21V8h8v13M12 14h.01"/>',laser:'<path d="M4 4h16v16H4zM6 15l5-5 4 4 3-3"/><path d="m12 2 2 3-2 3-2-3 2-3z"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v4m-5 0h10"/>',cpu:'<rect x="5" y="5" width="14" height="14" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2H3M16 5a3 3 0 0 1 0 6m2 9h3v-2a6 6 0 0 0-4-5.6"/>',box:'<path d="m12 2 9 5v10l-9 5-9-5V7l9-5zM3 7l9 5 9-5M12 12v10"/>',scan:'<path d="M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5M9 9h6v6H9z"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 14-1l1 5M4 12l1 5a8 8 0 0 0 14-1"/>',alert:'<path d="m12 3 10 18H2L12 3zM12 10v4m0 4h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',external:'<path d="M14 3h7v7M21 3l-10 10M20 13v7H4V4h7"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',eye:'<path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6S2 12 2 12z"/><circle cx="12" cy="12" r="2.5"/>',chart:'<path d="M3 3v18h18M7 16l4-5 4 2 5-7"/>',send:'<path d="M22 2 11 13M22 2l-7 20-4-9-9-4z"/>',book:'<path d="M4 19V4a2 2 0 0 1 2-2h14v18H6a2 2 0 0 1 0-4h14"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4V5zM12 5v14"/>'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.box}</svg>`;}
const plural=(n,s)=>`${n} ${s}${n===1?'':'s'}`;
function toast(message,isError=false){const x=$('#toast-root');x.innerHTML=`<div class="toast ${isError?'error':''}">${icon(isError?'alert':'checkcircle',16)} &nbsp; ${esc(message)}</div>`;clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>x.innerHTML='',4500);}
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json','X-Unlock-Client':'web'},credentials:'same-origin',...options});let j=await r.json();if(!r.ok)throw Error(j.error||`Request failed (${r.status})`);return j;}
async function refresh(){data=await api('/api/bootstrap');render();}
async function perform(payload){try{const result=await api('/api/action',{method:'POST',body:JSON.stringify(payload)});closeModal();await refresh();toast(result.message||'Saved successfully');return true;}catch(e){toast(e.message,true);return false;}}
function nav(to){view=to;category='All';query='';bookFilter='All';profileOpen=false;noticeOpen=false;sideOpen=false;render();window.scrollTo({top:0,behavior:'smooth'});}
function userAvatar(u){return `<span class="avatar" style="background:${esc(u.color||'#b8f487')}">${esc(u.avatar)}</span>`;}
const statusLabel=s=>s.replace(/_/g,' ');
function badge(s){return `<span class="status ${s}">${esc(statusLabel(s))}</span>`;}
function art(r){return `<div class="resource-art ${esc(r.accent)}"><div class="art-label">${esc(r.tag||'Campus resource')}</div><div class="art-icon">${icon(r.icon,95)}</div><div class="art-corner">U / LAB • ${esc(r.category.toUpperCase())}</div></div>`;}
function resourceCard(r){return `<article class="resource-card" data-text="${esc((r.name+' '+r.category+' '+r.location+' '+r.description).toLowerCase())}" data-category="${esc(r.category)}">${art(r)}<div class="resource-body"><div class="resource-type">${esc(r.category)} / ${r.requirements.length?'Verified access':'Open access'}</div><h3>${esc(r.name)}</h3><p class="resource-desc">${esc(r.description)}</p><div class="resource-meta"><span>${icon('pin',13)} ${esc(r.location)}</span><span>${icon('clock',13)} ${esc(r.availability)}</span></div><div class="resource-footer"><span class="chip ${r.eligibility.eligible?'':'warn'}">${icon(r.eligibility.eligible?'checkcircle':'lock',12)} ${r.eligibility.eligible?'You qualify':'Training needed'}</span><button class="card-arrow" data-open-resource="${esc(r.id)}" aria-label="View ${esc(r.name)}">${icon('arrowup',16)}</button></div></div></article>`;}
function sideNav(){const links=[['dashboard','home','Overview'],['explore','grid','Explore resources'],['bookings','calendar','My bookings'],['passport','shield','Skill Passport'],['owner','shield','Owner command'],['activity','history','Audit activity']];return `<aside class="sidebar ${sideOpen?'open':''}"><div class="brand"><div class="brandmark">${icon('box',24)}</div><div><strong>unlock<span style="color:var(--green)">.</span>lab</strong><small>Resource exchange</small></div></div><div class="nav-label">Workspace</div><nav class="nav" aria-label="Main navigation">${links.map(([key,ic,label])=>`<button data-nav="${key}" class="nav-item ${view===key?'active':''}">${icon(ic,19)} <span>${label}</span>${key==='owner'&&data.bookings.filter(b=>b.status==='pending').length?`<small style="margin-left:auto;background:#35442e;padding:2px 6px;border-radius:5px;color:var(--green)">${data.bookings.filter(b=>b.status==='pending').length}</small>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="sidebar-tip"><span class="kicker">✦ UNLOCK MORE</span><b>Great projects deserve great tools.</b><button data-nav="explore">Explore the lab ${icon('arrow',13)}</button></div><p class="side-legal">Built for curious minds · Judge demo</p></div></aside>`;}
function topBar(){const active={dashboard:'Overview',explore:'Explore resources',bookings:'My bookings',passport:'Skill Passport',owner:'Owner command',activity:'Audit history'}[view];return `<header class="topbar"><div style="display:flex;align-items:center;gap:14px"><button class="mobile-menu" data-mobile-menu aria-label="Open menu">${icon('menu')}</button><span class="crumb">Workspace &nbsp; / &nbsp; <b>${active}</b></span></div><div class="top-actions"><span class="chip dim" style="padding:8px 11px">${icon('shield',12)} Judge demo</span><button class="top-icon" aria-label="Notifications" data-notifications>${icon('bell',18)}${data.notifications.length?'<span class="notif-dot"></span>':''}</button><button class="profile" data-profile aria-label="Switch demo account">${userAvatar(data.user)}<div class="profile-meta"><b>${esc(data.user.name)}</b><small>${esc(data.user.role)} account</small></div>${icon('chevron',14)}</button></div>${profileOpen?`<div class="popover"><div class="pop-title">Switch demo identity</div>${data.users.map(u=>`<button class="pop-row ${u.id===data.user.id?'selected':''}" data-login="${u.id}">${userAvatar(u)}<span><b style="font-size:12px">${esc(u.name)}</b><span class="tiny">${esc(u.role)} · ${esc(u.department)}</span></span></button>`).join('')}<p class="small-note" style="padding:10px;line-height:1.5">Demo role switching is not production authentication.</p></div>`:''}${noticeOpen?`<div class="popover"><div class="pop-title">Notifications</div>${data.notifications.length?data.notifications.slice(0,7).map(n=>`<div class="notice"><strong>${esc(n.title)}</strong><small>${esc(n.body)}</small></div>`).join(''):'<p style="padding:12px;font-size:12px;color:#aaa">All caught up.</p>'}</div>`:''}</header>`;}
function stats(){const mine=data.bookings.filter(b=>b.userId===data.user.id),active=mine.filter(b=>['approved','active','return_pending'].includes(b.status)).length;return `<div class="stat-grid"><div class="stat"><div class="stat-title">${icon('box',14)} Resources to discover</div><div class="stat-value">${data.resources.length.toString().padStart(2,'0')}</div><p class="stat-note green">✦ Across 4 categories</p><span class="stat-mini">${icon('arrowup',18)}</span></div><div class="stat"><div class="stat-title">${icon('calendar',14)} My reservations</div><div class="stat-value">${mine.length.toString().padStart(2,'0')}</div><p class="stat-note">Full transaction history</p></div><div class="stat"><div class="stat-title">${icon('checkcircle',14)} My active access</div><div class="stat-value">${active.toString().padStart(2,'0')}</div><p class="stat-note green">Managed with care</p></div><div class="stat"><div class="stat-title">${icon('shield',14)} Verified account</div><div class="stat-value" style="font-size:24px">${data.user.verified?'Yes':'No'}</div><p class="stat-note green">${data.user.skills?.length||0} skills on passport</p></div></div>`;}
function hero(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A smarter campus starts here</div><h1>Ideas need access.<br><em>Not ownership.</em></h1><p class="lead">Discover incredible spaces and equipment around you. Book safely, share fairly, and make your next big idea happen.</p><div class="hero-actions"><button class="btn btn-primary" data-nav="explore">Explore resources ${icon('arrow',16)}</button><button class="btn btn-secondary" data-nav="bookings">My reservations ${icon('arrowup',15)}</button></div></div><div class="hero-scene"><div class="orb-ring one"></div><div class="orb-ring two"></div><div class="hero-object"><div class="cube-top"></div><div class="cube-front"></div><div class="cube-glass"></div></div><div class="scene-token one"><span class="token-icon">${icon('shield',16)}</span><span><b>Verified access</b><small>Skills first. Always.</small></span></div><div class="scene-token two"><span class="token-icon">${icon('spark',16)}</span><span><b>FairQueue™</b><small>Opportunities for all.</small></span></div><div class="scene-shadow"></div></div></section>`;}
function activityList(limit=5){return data.events.slice(0,limit).map(ev=>`<div class="activity-row"><span class="activity-icon">${icon(({request:'calendar',decision:'check',return:'box',checkin:'scan',checkout:'scan',incident:'alert',listing:'plus',cancel:'close'}[ev.type]||'history'),16)}</span><div style="flex:1"><b>${esc(ev.message)}</b><small>By ${esc(ev.actor)}</small></div><span class="activity-time">${new Date(ev.at).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span></div>`).join('');}
function dashboard(){return `${hero()}${stats()}<div class="section-heading"><div><h2>Featured spaces & tools</h2><p>Hand-picked opportunities for curious minds.</p></div><button class="link-button" data-nav="explore">Explore everything ${icon('arrow',15)}</button></div><div class="resource-grid">${data.resources.slice(0,3).map(resourceCard).join('')}</div><div class="two-col"><div class="panel"><div class="panel-header"><h3>Live activity feed</h3><span class="chip dim">${icon('history',12)} Auditable</span></div>${activityList(4)}</div><div class="panel"><div class="panel-header"><h3>How UNLOCK works</h3><span style="color:var(--green)">${icon('spark',20)}</span></div><div class="how-list">${[['01','Discover','Find the right tool or space'],['02','Get verified','Eligibility and fair-access review'],['03','Create & return','Check in, document and hand back']].map(x=>`<div class="how-step"><span class="step-no">${x[0]}</span><span><b>${x[1]}</b><small>${x[2]}</small></span></div>`).join('')}</div><div class="progress-track"><span></span></div><p style="color:#8c9a90;font-size:10px;margin-top:9px">Access powered by trust, not ownership.</p></div></div>`;}

const skillNames={'3d-print':'3D printing','camera':'Camera operation','workspace':'Computer & workspace safety','laser-safety':'Laser equipment safety'};
function passportPage(){
 const u=data.user,skills=Object.keys(skillNames),mine=data.trainingRequests.filter(t=>t.userId===u.id);
 return `<div class="heading-row"><div><div class="eyebrow">Your verified access</div><h1>Skill Passport.</h1><p>Earn institutional clearance through human-reviewed training, not automated guesses.</p></div><span class="chip">${icon('shield',13)} ${u.skills.length} verified skills</span></div>
 <div class="privacy-strip">${icon('shield',18)} Your eligibility is checked against owner-defined requirements. This demo uses fictional qualifications. A manager must review training before any new badge is granted.</div>
 <div class="passport-grid">${skills.map(skill=>{let approved=u.skills.includes(skill),pending=mine.find(t=>t.skill===skill&&t.status==='pending'),latest=[...mine].filter(t=>t.skill===skill).pop();return `<div class="panel passport-card"><span class="passport-symbol">${icon(approved?'checkcircle':'lock',27)}</span><h3>${esc(skillNames[skill])}</h3><p class="small-note">${approved?'Institution verified · access badge active':pending?'Verification is awaiting staff review':'Training evidence required before restricted access.'}</p>${approved?'<span class="chip">Verified</span>':pending?'<span class="chip dim">Review pending</span>':u.role==='student'?`<button class="btn btn-primary btn-sm" data-training-apply="${skill}">Request verification ${icon('arrow',13)}</button>`:'<span class="chip dim">Managed by staff</span>'}${latest?.status==='rejected'?`<p class="small-note">Review feedback: ${esc(latest.reason)}</p>`:''}</div>`;}).join('')}</div>
 <div class="panel section-space"><div class="panel-header"><h3>Training verification history</h3><span class="chip dim">Human oversight</span></div>${mine.length?mine.slice().reverse().map(t=>`<div class="queue-line"><div class="queue-info"><h3>${esc(skillNames[t.skill])} · ${badge(t.status)}</h3><p>${esc(t.evidence)}</p>${t.reason?`<p>${esc(t.reason)}</p>`:''}</div><span class="small-note">${fmtTime(t.requestedAt)}</span></div>`).join(''):'<p class="small-note">No verification requests yet. Existing badges are shown above.</p>'}</div>`;
}
function trainingReviewSection(){if(!['manager','admin'].includes(data.user.role))return '';
 const queue=data.trainingRequests.filter(t=>t.status==='pending');return `<div class="panel section-space"><div class="panel-header"><h3>Skill Passport · Human verification queue</h3><span class="chip">${queue.length} awaiting review</span></div>${queue.length?queue.map(t=>`<div class="queue-line"><div class="queue-info"><h3>${esc(t.student)} · ${esc(skillNames[t.skill]||t.skill)}</h3><p>${esc(t.evidence)}</p></div><button class="btn btn-primary btn-sm" data-training-review="${t.id}">Review evidence</button></div>`).join(''):'<p class="small-note">No qualifications awaiting staff review.</p>'}</div>`;
}
function trainingApplyModal(skill){openModal(`${modalHead('Request '+skillNames[skill],'A qualified manager must verify actual training before access is granted.')}<form data-form="requestTraining"><input type="hidden" name="skill" value="${skill}"><div class="form-group"><label class="label">Completed training, practical assessment or supervisor details</label><textarea class="field" name="evidence" minlength="12" required placeholder="Describe training completed, date and staff assessor. Use fictional demo information only."></textarea></div><div class="notice-box">This request does not automatically grant a qualification or equipment access.</div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Submit for human review</button></div></form>`);}
function trainingReviewModal(t){openModal(`${modalHead('Verify training',`${t.student} · ${skillNames[t.skill]}`)}<div class="notice-box">${esc(t.evidence)}<br><br>Verify evidence outside the system before approving. No automated safety decision.</div><form data-form="reviewTraining"><input type="hidden" name="trainingId" value="${t.id}"><div class="form-group"><label class="label">Decision</label><select class="field" name="decision"><option value="approve">Approve verified badge</option><option value="reject">Reject with explanation</option></select></div><div class="form-group"><label class="label">Evidence review and justification</label><textarea class="field" name="note" minlength="10" required placeholder="Verified by responsible lab coordinator after practical assessment"></textarea></div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Record authorised decision</button></div></form>`);}

function explore(){let available=data.resources.filter(r=>(category==='All'||category==='For you'&&r.eligibility.eligible||r.category===category)&&(!query||`${r.name} ${r.description} ${r.location}`.toLowerCase().includes(query.toLowerCase())));return `<div class="heading-row"><div><div class="eyebrow">Made to be shared</div><h1>Explore the possibilities.</h1><p>Make use of what's already here, beautifully and responsibly.</p></div><span class="chip dim">${icon('box',13)} ${data.resources.length} resources</span></div><div class="filters"><label class="search">${icon('search',17)}<input id="resource-search" placeholder="Search cameras, labs, printers..." value="${esc(query)}" aria-label="Search resources"></label>${['All','For you','Fabrication','Media','Spaces','Technology'].map(c=>`<button class="filter-pill ${category===c?'active':''}" data-filter="${c}">${esc(c)}</button>`).join('')}</div><div class="resource-grid" id="resource-results">${available.map(resourceCard).join('')}</div>${!available.length?`<div class="empty-state" style="margin-top:18px">${icon('search',30)}<h3>No matching resources</h3><p>Try a different keyword or category.</p><button class="btn btn-secondary btn-sm" data-clear-filters>Clear filters</button></div>`:''}`;}
function bookingActions(b){const buttons=[];if(b.isMine){if(['approved'].includes(b.status))buttons.push(`<button class="btn btn-primary btn-sm" data-act="checkin" data-b="${b.id}">${icon('scan',13)} Check in</button>`);if(['approved','active'].includes(b.status)&&b.extension?.status!=='pending')buttons.push(`<button class="btn btn-ghost btn-sm" data-act="requestExtension" data-b="${b.id}">Extend time</button>`);if(b.status==='active')buttons.push(`<button class="btn btn-primary btn-sm" data-act="checkout" data-b="${b.id}">${icon('box',13)} Submit return</button>`);if(['pending','approved','waitlisted'].includes(b.status))buttons.push(`<button class="btn btn-ghost btn-sm" data-act="cancel" data-b="${b.id}">Cancel</button>`);if(['active','return_pending','returned'].includes(b.status))buttons.push(`<button class="btn btn-ghost btn-sm" data-act="incident" data-b="${b.id}">Report issue</button>`);}if(b.canManage){if(['pending','waitlisted'].includes(b.status))buttons.push(`<button class="btn btn-primary btn-sm" data-act="review" data-b="${b.id}">Review</button>`);if(b.extension?.status==='pending')buttons.push(`<button class="btn btn-ghost btn-sm" data-act="reviewExtension" data-b="${b.id}">Review extension</button>`);if(b.status==='return_pending')buttons.push(`<button class="btn btn-primary btn-sm" data-act="confirmReturn" data-b="${b.id}">Confirm return</button>`);}return buttons.join('');}
function bookingCard(b){const r=data.resources.find(r=>r.id===b.resourceId);return `<article class="booking-item"><div class="booking-icon">${icon(r?.icon||'box',30)}</div><div class="booking-info"><div style="display:flex;align-items:center;gap:9px;flex-wrap:wrap">${badge(b.status)} <span style="color:#a7b1bb;font-size:10px">#${esc(b.id.slice(0,8))}</span></div><h3>${esc(b.resource)}</h3><p>${icon('calendar',12)} ${fmtDate(b.date)} &nbsp; ${icon('clock',12)} ${esc(b.start)}–${esc(b.end)} &nbsp; ${icon('users',12)} ${esc(b.user||'')}</p><div class="booking-bottom"><span class="small-note">${icon('info',12)} ${esc(b.reason||b.purpose)}</span></div></div><div class="booking-actions">${bookingActions(b)}<button class="btn btn-ghost btn-sm" data-act="details" data-b="${b.id}">${icon('eye',14)}</button></div></article>`;}
function bookingsPage(){const relevant=data.bookings.filter(b=>b.isMine||b.canManage);const selected=relevant.filter(b=>bookFilter==='All'||b.status===bookFilter);return `<div class="heading-row"><div><div class="eyebrow">Your access, your history</div><h1>Booking journeys.</h1><p>Track requests, check-ins, returns and decisions in one place.</p></div><button class="btn btn-primary" data-nav="explore">${icon('plus',15)} New request</button></div><div class="filters">${['All','pending','approved','active','return_pending','waitlisted','returned'].map(s=>`<button class="filter-pill ${bookFilter===s?'active':''}" data-book-filter="${s}">${s==='All'?'All':statusLabel(s)}</button>`).join('')}</div><div class="booking-list">${selected.length?selected.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(bookingCard).join(''):`<div class="empty-state">${icon('calendar',32)}<h3>Nothing here yet</h3><p>Once you request a resource, its entire journey appears here.</p><button class="btn btn-primary btn-sm" data-nav="explore">Explore resources</button></div>`}</div>`;}
function ownerPage(){const canManage=['owner','manager','admin'].includes(data.user.role);if(!canManage)return `<div class="heading-row"><div><div class="eyebrow">For authorised custodians</div><h1>Owner command.</h1><p>Approvals, safety and returns belong with the people responsible for the resource.</p></div></div><div class="empty-state">${icon('lock',34)}<h3>Manager access required</h3><p>Switch to Mira Kapoor (owner) or Dr. Kiran Shah (manager) using the profile menu to try this workflow.</p></div>`;
const managed=data.bookings.filter(b=>b.canManage),pending=managed.filter(b=>['pending','waitlisted'].includes(b.status)),returns=managed.filter(b=>b.status==='return_pending'),incidents=data.incidents.filter(i=>data.resources.some(r=>r.id===i.resourceId&&(data.user.role==='manager'||r.ownerId===data.user.id)));
return `<div class="heading-row"><div><div class="eyebrow">Custody with clarity</div><h1>Owner command.</h1><p>Every decision is explainable, every handover accountable.</p></div><button class="btn btn-primary" data-act="addResource">${icon('plus',16)} List a resource</button></div><div class="owner-dashboard"><div class="owner-summary"><b>${String(pending.length).padStart(2,'0')}</b><p>Requests to review ${icon('calendar',14)}</p></div><div class="owner-summary"><b>${String(returns.length).padStart(2,'0')}</b><p>Returns awaiting sign-off ${icon('box',14)}</p></div><div class="owner-summary"><b>${String(incidents.filter(i=>i.status==='open').length).padStart(2,'0')}</b><p>Incidents needing review ${icon('alert',14)}</p></div></div><div class="panel"><div class="panel-header"><h3>FairQueue · Requests and waiting list</h3><span class="chip">${icon('scale',12)} <span>Transparent priority</span></span></div>${pending.length?pending.sort((a,b)=>b.requesterScore.score-a.requesterScore.score).map(b=>`<div class="queue-line"><span class="avatar">${esc(b.user?.split(' ').map(x=>x[0]).join('').slice(0,2)||'ST')}</span><div class="queue-info"><h3>${esc(b.resource)} <span class="small-note">· ${esc(b.user)}</span></h3><p>${fmtDate(b.date)} · ${esc(b.start)}–${esc(b.end)} · ${esc(b.purpose)}</p><p>${badge(b.status)} <span style="margin-left:6px">${esc(b.requesterScore.explanation)}</span></p></div><div class="queue-right"><span class="fair-meter">${b.requesterScore.score} pts</span><button class="btn btn-primary btn-sm" data-act="review" data-b="${b.id}">Review ${icon('arrow',13)}</button></div></div>`).join(''):`<p class="small-note" style="padding:20px 0">No requests waiting. Ask a student to submit one.</p>`}</div><div class="two-col"><div class="panel"><div class="panel-header"><h3>Returns awaiting confirmation</h3></div>${returns.length?returns.map(b=>`<div class="queue-line"><div class="queue-info"><h3>${esc(b.resource)}</h3><p>${esc(b.user)} · Final condition: ${esc(b.finalCondition||'Not recorded')}</p></div><button class="btn btn-primary btn-sm" data-act="confirmReturn" data-b="${b.id}">Verify return</button></div>`).join(''):'<p class="small-note">No returns pending verification.</p>'}</div><div class="panel"><div class="panel-header"><h3>Incident resolution inbox</h3></div>${incidents.length?incidents.map(i=>{const b=data.bookings.find(b=>b.id===i.bookingId);return `<div class="queue-line"><div class="queue-info"><h3>${esc(data.resources.find(r=>r.id===i.resourceId)?.name||'Resource')} ${badge(i.status)}</h3><p>${esc(i.description)}</p></div>${i.status==='open'?`<button class="btn btn-ghost btn-sm" data-act="resolveIncident" data-b="${i.bookingId}" data-incident="${i.id}">Resolve</button>`:''}</div>`;}).join(''):'<p class="small-note">No incidents recorded.</p>'}</div></div>${trainingReviewSection()}<div class="section-heading"><div><h2>Registered resources</h2><p>All listings currently visible to the community.</p></div>${data.user.role==='manager'?`<button class="btn btn-ghost btn-sm" data-act="reset">${icon('refresh',13)} Reset demo data</button>`:''}</div><div class="resource-grid">${data.resources.slice(0,6).map(resourceCard).join('')}</div>`;}
function activityPage(){return `<div class="heading-row"><div><div class="eyebrow">Evidence that stays</div><h1>Nothing gets lost.</h1><p>A chronological, auditable trail of all important actions and decisions.</p></div><span class="chip dim">${icon('lock',13)} Demo audit log</span></div><div class="privacy-strip">${icon('shield',18)} Audit events include actor, action, timestamp, booking reference and explanation. In a real institution, access to logs and personal data must be restricted by role.</div><div class="panel section-space"><div class="panel-header"><h3>Transaction timeline</h3><span class="small-note">${data.events.length} recent events</span></div>${data.events.map(e=>`<div class="audit-row"><div class="audit-rail"><span class="activity-icon">${icon(e.type==='incident'?'alert':e.type==='decision'?'checkcircle':'history',15)}</span></div><div class="audit-content"><b>${esc(e.message)}</b><p>Performed by ${esc(e.actor)} · ${fmtTime(e.at)} ${e.bookingId?'· Booking '+esc(e.bookingId.slice(0,8)):''}</p></div><span class="chip neutral">${esc(e.type)}</span></div>`).join('')}</div>`;}
function assistantUi(){return `<button class="assistant-button" data-assistant>${icon('spark',18)} Ask LabMate</button>${assistantOpen?`<div class="assistant-panel"><div class="assistant-head"><div><b>${icon('spark',16)} LabMate</b><p class="small-note">${esc(data.assistantMode)} · safety decisions stay human-led</p></div><button class="close" data-assistant-close aria-label="Close assistant">${icon('close',15)}</button></div><div class="assistant-content" id="chat-history">${chat.map(m=>`<div class="bubble ${m.from==='user'?'me':''}">${esc(m.text)}</div>`).join('')}</div><form class="chat-input" id="chat-form"><input id="chat-question" aria-label="Ask LabMate" placeholder="Try: What can I book?" required maxlength="240"><button aria-label="Send" type="submit">${icon('send',16)}</button></form></div>`:''}`;}
function labMateReply(text){let s=text.toLowerCase(),u=data.user;if(/qualif|train|eligible|passport/.test(s)){const qualified=data.resources.filter(r=>r.eligibility.eligible);return `Your current Skill Passport qualifies you for ${qualified.length} of ${data.resources.length} resources: ${qualified.map(r=>r.name).join(', ')}. Resources requiring missing skills are shown as “Training needed.” A coordinator must verify new training.`;}if(/book|reserv|status|request/.test(s)){let b=data.bookings.filter(b=>b.userId===u.id);return b.length?`You have ${b.length} recorded booking(s). Most recent: ${b[b.length-1].resource} — ${statusLabel(b[b.length-1].status)}. Open My bookings to see actions and reasons.`:'You have no bookings yet. Open Explore, choose an eligible resource, and submit a time-slot request.';}if(/fair|queue|priorit|wait/.test(s))return 'FairQueue prioritises eligible requests with fewer recent usage hours, then earlier submissions when scores tie. A resource has a maximum of 2 outstanding requests per user, plus a 6-hour rolling-week limit. Managers can override with an auditable reason.';if(/damage|return|check.in|check.out|qr|incident/.test(s))return 'After owner approval, enter the resource handover code and document its initial condition. On return, record the final condition and any damage. The owner verifies the return; incidents go to human review.';if(/camera|photo|video/.test(s))return 'Try the Sony A7 IV Creator Kit (camera training required) or Podcast Recording Suite (no special training). Both are in the Media Center.';if(/printer|fabricat|laser|3d/.test(s))return 'The Prusa MK4 3D Printer requires 3D-print training. The laser cutter additionally requires laser-safety training and staff supervision. Check your eligibility before requesting.';if(/room|studio|space/.test(s))return 'The Collaborative Design Studio is available without specialised training and seats up to 12. Check the access rules and hours on its resource card.';return `You can explore ${data.resources.length} resources, request access, follow fair allocation, and complete the handover. Try asking about training, the 3D printer, fairness, booking status, or return procedures.`;}
function render(){if(!data)return;$('#app').innerHTML=`<div class="app-shell">${sideNav()}<div class="mobile-overlay ${sideOpen?'visible':''}" data-mobile-overlay></div><div class="main">${topBar()}<main class="page">${({dashboard,explore,bookings:bookingsPage,passport:passportPage,owner:ownerPage,activity:activityPage}[view]||dashboard)()}</main><footer class="footer">UNLOCK Lab — Fictional demonstration data · Do not use for real access control · © 2026</footer></div></div>${assistantUi()}`;const scene=$('.hero-scene');if(scene)scene.addEventListener('pointermove',e=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rc=scene.getBoundingClientRect();let x=(e.clientX-rc.left)/rc.width-.5,y=(e.clientY-rc.top)/rc.height-.5;scene.style.transform=`rotateY(${x*8}deg) rotateX(${-y*8}deg)`;});if(scene)scene.addEventListener('pointerleave',()=>scene.style.transform='');}
function openModal(content,wide=false){photoValue='';$('#modal-root').innerHTML=`<div class="modal-shade" data-shade><div class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Resource action">${content}</div></div>`;const el=$('#modal-root .field');if(el)el.focus();}
function closeModal(){$('#modal-root').innerHTML='';photoValue='';}
const modalHead=(title,subtitle='')=>`<div class="dialog-head"><div><span class="eyebrow">UNLOCK LAB / SECURE FLOW</span><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close" data-close aria-label="Close dialog">${icon('close',17)}</button></div>`;
function resourceDetail(r){const matching=(r.busySlots||[]).sort((a,b)=>a.date.localeCompare(b.date));openModal(`${modalHead(r.name,'Verified campus resource · '+r.category)}<div class="detail-hero">${art(r)}<div><span class="chip ${r.eligibility.eligible?'':'warn'}">${icon(r.eligibility.eligible?'shield':'lock',13)} ${esc(r.eligibility.description)}</span><p style="margin-top:14px">${esc(r.description)}</p><p style="margin-top:10px;color:#d7e4de">Managed by ${esc(r.owner)}</p></div></div><div class="detail-lines"><div class="detail-line">${icon('pin',16)} ${esc(r.location)}</div><div class="detail-line">${icon('clock',16)} Bookable ${esc(r.availability)} · Maximum ${r.limit} hours / booking</div><div class="detail-line">${icon('shield',16)} ${esc(r.conditions)}</div></div><div class="section-space"><span class="label">Required training</span><div class="requirement-list">${r.requirements.length?r.requirements.map(s=>`<span class="req ${data.user.skills.includes(s)?'':'unmet'}">${icon(data.user.skills.includes(s)?'check':'lock',12)} ${esc(s.replace(/-/g,' '))}</span>`).join(''):'<span class="req">No specialised training needed</span>'}</div></div>${matching.length?`<div class="notice-box warn">${icon('calendar',14)} Already approved: ${matching.slice(0,3).map(b=>`${fmtDate(b.date)} ${b.start}–${b.end}`).join('; ')}. Overlapping requests go to a fair waitlist.</div>`:''}<div class="notice-box">${icon('scan',14)} Handover code (judge demo): <strong>${esc(r.code)}</strong> — enter this during check-in. In production, the code would be visible only at the physical resource.</div><div class="dialog-actions"><button class="btn btn-ghost" data-close>Close</button>${data.user.role==='student'?`<button class="btn btn-primary" data-book-resource="${r.id}" ${r.eligibility.eligible?'':'disabled'}>${icon('calendar',15)} ${r.eligibility.eligible?'Request this resource':'Training required'}</button>`:''}</div>`,true);}
function requestModal(r){openModal(`${modalHead('Reserve '+r.name,'Tell the owner what you need and when you need it.')}<form data-form="request" data-resource="${r.id}"><div class="form-grid"><div class="form-group"><label class="label" for="date">Booking date</label><input class="field" id="date" name="date" type="date" min="${today()}" value="${tomorrow()}" required></div><div class="form-group"><label class="label" for="start">Start time</label><input class="field" id="start" name="start" type="time" value="10:00" required></div><div class="form-group"><label class="label" for="end">End time</label><input class="field" id="end" name="end" type="time" value="12:00" required></div><div class="form-group"><span class="label">Resource hours</span><div class="notice-box" style="margin-top:0">${esc(r.availability)} · Max ${r.limit}h per session</div></div></div><div class="form-group"><label class="label" for="purpose">Project or purpose</label><textarea class="field" name="purpose" id="purpose" required minlength="8" placeholder="e.g. Printing the enclosure for our assistive robotics prototype"></textarea></div><div class="notice-box">${icon('shield',14)} ${esc(r.eligibility.description)}. Booking is subject to manual approval, availability and fair-use limits.</div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-open-resource="${r.id}">Back</button><button class="btn btn-primary" type="submit">Submit access request ${icon('arrow',15)}</button></div></form>`);}
function photoField(){return `<div class="form-group"><label class="label">Condition photograph (optional)</label><label class="upload">${icon('upload',18)} <span id="photo-label">Choose an image (compressed locally)</span><input type="file" id="condition-photo" accept="image/*"><img id="photo-preview" class="upload-preview" alt="" style="display:none"></label><p class="form-hint">Use only permissioned demonstration photos. Never upload private institutional images.</p></div>`;}
function bookingModal(action,b,incidentId){const r=data.resources.find(r=>r.id===b.resourceId),title={review:'Review access request',checkin:'Secure check-in',checkout:'Document return',confirmReturn:'Confirm handover',incident:'Report an incident',resolveIncident:'Review reported incident',cancel:'Cancel reservation',details:'Booking record',reset:'Reset demo workspace',requestExtension:'Request more time',reviewExtension:'Review time extension'}[action];if(action==='requestExtension')return openModal(`${modalHead(title,`Request an extension for ${b.resource}`)}<form data-form="requestExtension" data-booking="${b.id}"><div class="notice-box">Current booking ends ${esc(b.end)}. Extensions require owner approval, available capacity and compliance with fair-use limits.</div><div class="form-group"><label class="label">New end time</label><input class="field" type="time" name="newEnd" required min="${esc(b.end)}" max="${esc(r.closes)}"></div><div class="form-group"><label class="label">Why do you need more time?</label><textarea class="field" name="reason" minlength="10" required placeholder="Explain the work and why a longer session is necessary"></textarea></div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Request extension</button></div></form>`);
if(action==='reviewExtension')return openModal(`${modalHead(title,`Review extension · ${b.resource}`)}<div class="notice-box">Current end ${esc(b.end)} → requested ${esc(b.extension?.newEnd)}<br>Reason: ${esc(b.extension?.reason)}</div><form data-form="reviewExtension" data-booking="${b.id}"><div class="form-group"><label class="label">Decision</label><select class="field" name="decision"><option value="approve">Approve if slot is free</option><option value="reject">Reject with reason</option></select></div><div class="form-group"><label class="label">Written justification</label><textarea class="field" name="note" required minlength="8" placeholder="Approved based on available equipment and fair-use policy"></textarea></div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Record extension decision</button></div></form>`);
if(action==='details')return openModal(`${modalHead(title,`Booking #${b.id}`)}<div class="detail-lines"><div class="detail-line">${icon('box',17)} ${esc(b.resource)}</div><div class="detail-line">${icon('users',17)} ${esc(b.user)}</div><div class="detail-line">${icon('calendar',17)} ${fmtDate(b.date)} ${esc(b.start)}–${esc(b.end)}</div><div class="detail-line">${icon('shield',17)} ${badge(b.status)} · ${esc(b.reason)}</div><div class="detail-line">${icon('book',17)} ${esc(b.purpose)}</div>${b.initialCondition?`<div class="detail-line">${icon('check',17)} Initial: ${esc(b.initialCondition)} · ${esc(b.initialNote||'No notes')}</div>`:''}${b.finalCondition?`<div class="detail-line">${icon('check',17)} Final: ${esc(b.finalCondition)} · ${esc(b.finalNote||'No notes')}</div>`:''}${b.ownerNote?`<div class="detail-line">${icon('shield',17)} Owner sign-off: ${esc(b.ownerNote)}</div>`:''}</div><div class="timeline-mini">${data.events.filter(e=>e.bookingId===b.id).reverse().map(e=>`<div>${esc(e.message)}<small>${fmtTime(e.at)}</small></div>`).join('')||'<div>No actions logged yet.</div>'}</div>${b.initialPhoto||b.finalPhoto?`<div class="form-grid">${b.initialPhoto?`<div><span class="label">Before</span><img src="${esc(b.initialPhoto)}" style="max-width:100%;max-height:160px;border-radius:10px" alt="Initial condition"></div>`:''}${b.finalPhoto?`<div><span class="label">After</span><img src="${esc(b.finalPhoto)}" style="max-width:100%;max-height:160px;border-radius:10px" alt="Returned condition"></div>`:''}</div>`:''}<div class="dialog-actions"><button class="btn btn-primary" data-close>Done</button></div>`);
if(action==='review')return openModal(`${modalHead(title,`Human review · ${b.resource}`)}<div class="notice-box">${icon('shield',15)} ${esc(b.user)} · ${fmtDate(b.date)} ${esc(b.start)}–${esc(b.end)}<br>${esc(b.purpose)}</div><div class="form-group" style="margin-top:15px"><span class="label">FairQueue assessment</span><div class="fair-meter">Priority ${b.requesterScore.score} points · ${esc(b.requesterScore.explanation)}</div><p class="form-hint">Lower previous usage improves priority. Human overrides require a recorded reason containing “override”.</p></div><form data-form="review" data-booking="${b.id}"><div class="form-group"><label class="label">Decision</label><select name="decision" class="field"><option value="approve">Approve access</option><option value="waitlist">Place on waiting list</option><option value="reject">Reject with reason</option></select></div><div class="form-group"><label class="label">Reason / human override explanation</label><textarea class="field" name="note" placeholder="Approved: training verified, access conditions met"></textarea></div><div class="dialog-actions"><button type="button" class="btn btn-ghost" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save auditable decision ${icon('check',15)}</button></div></form>`);
if(action==='checkin')return openModal(`${modalHead(title,`Borrower's physical handover · ${b.resource}`)}<div class="notice-box">${icon('scan',15)} For this judge demo, use the resource's QR label code: <strong>${esc(r.code)}</strong>. A production deployment must bind codes to physical assets.</div><form data-form="checkin" data-booking="${b.id}"><div class="form-group" style="margin-top:18px"><label class="label" for="code">Scan / enter asset handover code</label><input class="field" id="code" name="code" required autocomplete="off" placeholder="e.g. MK4-2048"></div><div class="form-group"><label class="label">Condition before use</label><select class="field" name="condition"><option>Excellent</option><option>Good</option><option>Worn</option><option>Damaged</option></select></div><div class="form-group"><label class="label">Initial observations</label><textarea class="field" name="note" placeholder="Describe scratches, missing accessories or existing wear"></textarea></div>${photoField()}<div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Confirm custody ${icon('checkcircle',15)}</button></div></form>`);
if(action==='checkout')return openModal(`${modalHead(title,`Borrower return report · ${b.resource}`)}<div class="notice-box">Record the actual condition. Damage will create an incident for human investigation, not an automatic penalty.</div><form data-form="checkout" data-booking="${b.id}"><div class="form-group" style="margin-top:18px"><label class="label">Condition after use</label><select class="field" name="condition"><option>Excellent</option><option>Good</option><option>Worn</option><option>Damaged</option></select></div><div class="form-group"><label class="label">Return observations</label><textarea class="field" name="note" placeholder="Record anything changed, missing or delayed"></textarea></div>${photoField()}<div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Submit return to owner ${icon('arrow',15)}</button></div></form>`);
if(action==='confirmReturn')return openModal(`${modalHead(title,`Owner sign-off · ${b.resource}`)}<div class="notice-box">Initial condition: <b>${esc(b.initialCondition)}</b><br>Final condition: <b>${esc(b.finalCondition)}</b><br>Borrower note: ${esc(b.finalNote||'None')}</div><form data-form="confirmReturn" data-booking="${b.id}"><div class="form-group" style="margin-top:18px"><label class="label">Owner verification note</label><textarea class="field" name="note" placeholder="Equipment received; accessories accounted for" required minlength="8"></textarea></div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Not yet</button><button class="btn btn-primary" type="submit">Confirm full return ${icon('checkcircle',15)}</button></div></form>`);
if(action==='incident')return openModal(`${modalHead(title,`Human-review incident record · ${b.resource}`)}<form data-form="incident" data-booking="${b.id}"><div class="form-group"><label class="label">What happened?</label><textarea class="field" name="description" required minlength="10" placeholder="Describe damage, late return, missing part or scheduling conflict"></textarea></div><div class="notice-box warn">An incident report is an allegation/observation, not proof of fault. No automatic penalties are imposed.</div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">File incident ${icon('alert',15)}</button></div></form>`);
if(action==='resolveIncident')return openModal(`${modalHead(title,'Record the authorised manager’s outcome')}<form data-form="resolveIncident" data-booking="${b.id}" data-incident="${incidentId}"><div class="form-group"><label class="label">Human resolution and explanation</label><textarea class="field" name="resolution" required minlength="8" placeholder="Inspection complete, no damage / corrective action agreed"></textarea></div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Record resolution</button></div></form>`);
if(action==='cancel')return openModal(`${modalHead(title,`${b.resource} · ${fmtDate(b.date)}`)}<form data-form="cancel" data-booking="${b.id}"><div class="form-group"><label class="label">Reason for cancellation</label><textarea class="field" name="note" placeholder="Plans changed / booking no longer required"></textarea></div><div class="dialog-actions"><button class="btn btn-ghost" type="button" data-close>Keep booking</button><button class="btn btn-danger" type="submit">Cancel this booking</button></div></form>`);
}
function addResourceModal(){openModal(`${modalHead('List a campus resource','Set clear conditions, owner responsibilities and eligibility before publishing.')}<form data-form="addResource"><div class="form-grid"><div class="form-group"><label class="label">Resource name</label><input class="field" required minlength="4" name="name" placeholder="Arduino robotics toolkit"></div><div class="form-group"><label class="label">Category</label><select class="field" name="category"><option>Technology</option><option>Fabrication</option><option>Media</option><option>Spaces</option></select></div></div><div class="form-group"><label class="label">Location</label><input class="field" name="location" required minlength="4" placeholder="Innovation Hub · Bay 04"></div><div class="form-group"><label class="label">Resource description</label><textarea class="field" name="description" placeholder="Who should use it and for what?"></textarea></div><div class="form-group"><label class="label">Safety and usage conditions</label><textarea class="field" name="conditions" required minlength="8" placeholder="Supervision, accessories, return requirements and restrictions"></textarea></div><div class="form-group"><span class="label">Training or skill requirements</span><div class="pill-row">${[['3d-print','3D printing'],['camera','Camera handling'],['workspace','Computer lab access'],['laser-safety','Laser safety']].map(x=>`<label class="choose"><input type="checkbox" name="requirements" value="${x[0]}">${x[1]}</label>`).join('')}</div></div><div class="dialog-actions"><button type="button" class="btn btn-ghost" data-close>Cancel</button><button type="submit" class="btn btn-primary">Publish resource ${icon('plus',15)}</button></div></form>`);}
function resetModal(){openModal(`${modalHead('Reset demonstration','Restore all original fictional resources, bookings and activity.')}<p class="lead">This clears every change made within this local demo workspace. It cannot be undone.</p><form data-form="reset"><div class="dialog-actions"><button type="button" class="btn btn-ghost" data-close>Keep current demo</button><button type="submit" class="btn btn-danger">Reset demo records</button></div></form>`);}
async function handleFile(input){const file=input.files?.[0];if(!file)return;if(file.size>8_000_000){toast('Choose a photo smaller than 8 MB.',true);return;}let blob=await createImageBitmap(file).catch(()=>null);if(!blob){toast('Could not process this image.',true);return;}const max=650,scale=Math.min(1,max/Math.max(blob.width,blob.height)),canvas=document.createElement('canvas');canvas.width=Math.round(blob.width*scale);canvas.height=Math.round(blob.height*scale);canvas.getContext('2d').drawImage(blob,0,0,canvas.width,canvas.height);photoValue=canvas.toDataURL('image/jpeg',.66);blob.close();if(photoValue.length>750000){toast('Photo too complex. Please choose a simpler image.',true);photoValue='';return;}$('#photo-preview').src=photoValue;$('#photo-preview').style.display='block';$('#photo-label').textContent='Photo ready · '+Math.round(photoValue.length/1024)+' KB';}

document.addEventListener('click',async e=>{let el=e.target.closest('button,[data-shade],[data-mobile-overlay]');if(!el)return;
if(el.dataset.nav){nav(el.dataset.nav);return;}
if(el.dataset.trainingApply){trainingApplyModal(el.dataset.trainingApply);return;}
if(el.dataset.trainingReview){const t=data.trainingRequests.find(x=>x.id===el.dataset.trainingReview);if(t)trainingReviewModal(t);return;}
if(el.hasAttribute('data-mobile-menu')){sideOpen=!sideOpen;render();return;}
if(el.hasAttribute('data-mobile-overlay')){sideOpen=false;render();return;}
if(el.hasAttribute('data-profile')){profileOpen=!profileOpen;noticeOpen=false;render();return;}
if(el.hasAttribute('data-notifications')){noticeOpen=!noticeOpen;profileOpen=false;render();return;}
if(el.dataset.login){try{await api('/api/demo-login',{method:'POST',body:JSON.stringify({userId:el.dataset.login})});view=el.dataset.login==='owner1'||el.dataset.login==='manager1'?'owner':'dashboard';await refresh();toast('Switched to the '+data.user.role+' demo account');}catch(er){toast(er.message,true);}return;}
if(el.hasAttribute('data-close')||el.dataset.shade!==undefined&&e.target===el){closeModal();return;}
if(el.dataset.openResource){const r=data.resources.find(x=>x.id===el.dataset.openResource);if(r)resourceDetail(r);return;}
if(el.dataset.bookResource){const r=data.resources.find(x=>x.id===el.dataset.bookResource);if(r)requestModal(r);return;}
if(el.dataset.filter){category=el.dataset.filter;render();return;}
if(el.dataset.bookFilter){bookFilter=el.dataset.bookFilter;render();return;}
if(el.hasAttribute('data-clear-filters')){query='';category='All';render();return;}
if(el.hasAttribute('data-assistant')){assistantOpen=!assistantOpen;render();return;}
if(el.hasAttribute('data-assistant-close')){assistantOpen=false;render();return;}
if(el.dataset.act){if(el.dataset.act==='addResource')addResourceModal();else if(el.dataset.act==='reset')resetModal();else{const b=data.bookings.find(x=>x.id===el.dataset.b);if(b)bookingModal(el.dataset.act,b,el.dataset.incident);}return;}
});
document.addEventListener('input',e=>{if(e.target.id==='resource-search'){query=e.target.value.toLowerCase();const grid=$('#resource-results');if(!grid)return;let matches=0;grid.querySelectorAll('.resource-card').forEach(c=>{const show=c.dataset.text.includes(query);c.style.display=show?'':'none';if(show)matches++;});}});
document.addEventListener('change',e=>{if(e.target.id==='condition-photo')handleFile(e.target);});
document.addEventListener('submit',async e=>{if(e.target.id==='chat-form'){e.preventDefault();let input=$('#chat-question'),text=input.value.trim();if(!text)return;chat.push({from:'user',text});let answer=labMateReply(text);if(data.assistantMode==='AI model connected'){try{const result=await api('/api/assistant',{method:'POST',body:JSON.stringify({question:text})});answer=result.answer;}catch{answer='The live model is unavailable, so I am using the offline guide. '+answer;}}chat.push({from:'bot',text:answer});render();const history=$('#chat-history');if(history)history.scrollTop=history.scrollHeight;return;}
const f=e.target;if(!f.dataset.form)return;e.preventDefault();const vals=Object.fromEntries(new FormData(f).entries());let p={action:f.dataset.form,...vals};if(f.dataset.resource)p.resourceId=f.dataset.resource;if(f.dataset.booking)p.bookingId=f.dataset.booking;if(f.dataset.incident)p.incidentId=f.dataset.incident;if(['checkin','checkout'].includes(p.action))p.photo=photoValue;if(p.action==='addResource')p.requirements=[...f.querySelectorAll('input[name="requirements"]:checked')].map(n=>n.value);const btn=f.querySelector('button[type="submit"]');if(btn){btn.disabled=true;btn.textContent='Saving…';}await perform(p);if(btn){btn.disabled=false;btn.textContent='Try again';}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();profileOpen=false;noticeOpen=false;sideOpen=false;render();}});
$('#app').innerHTML='<div class="loading">✦ &nbsp; Unlocking possibilities…</div>';
refresh().catch(e=>{$('#app').innerHTML=`<div class="loading" style="text-align:center;padding:30px"><div><h2>Unable to load your workspace</h2><p style="font-size:13px;color:#abb;margin:15px">${esc(e.message)}</p><button class="btn btn-primary" onclick="location.reload()">Retry</button></div></div>`;});
